/**
 * Hand-authored relief of the real Earth. All coordinates are [lon, lat] in
 * degrees. Heights in metres, widths in km. These tables drive the procedural
 * terrain model in elevation.ts; no external elevation data is used.
 */

/** Range vertex: [lon, lat, typical crest height m, half-width km]. */
export type RangePt = [number, number, number, number];
export interface RangeDef { name: string; pts: RangePt[] }

export type LL = [number, number];
/** Linear gradient: [lonA, latA, elevA, lonB, latB, elevB]. */
export type Tilt = [number, number, number, number, number, number];

export interface PlateauDef {
  name: string;
  poly: LL[];
  elev: number;
  /** Edge ramp width in km (default 120). */
  soft?: number;
  tilt?: Tilt;
  /** Extra hilly relief as a fraction of the elevation (default 0.1). */
  rough?: number;
  /** Basin-and-range style parallel ridges: amplitude m, orientation (deg from north), spacing km. */
  ridges?: [number, number, number];
}

export interface BasinDef {
  name: string;
  poly: LL[];
  /** Maximum elevation inside (min-combine). */
  cap: number;
  soft?: number;
  tilt?: Tilt;
}

export interface PeakDef { name: string; lon: number; lat: number; elev: number; r: number }

/** Circular depression: land is pulled down to (near) sea level. */
export interface DepressionDef { name: string; lon: number; lat: number; r: number; real: number }

export interface SeaRegionDef {
  name: string;
  poly: LL[];
  /** Typical floor depth (positive metres). */
  depth: number;
  soft?: number;
}

export interface RidgeDef { name: string; pts: LL[]; crest: number; halfKm: number }
export interface TrenchDef { name: string; pts: LL[]; depth: number; halfKm: number }

